begin;create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table support_fixture(campus uuid,support uuid);grant select,insert,update on support_fixture to cuevo_api;
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','df100000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Support course','School source','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id)values('10000000-0000-4000-8000-000000000001','df110000-0000-4000-8000-000000000001','df100000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Support task','School task',10,'61000000-0000-4000-8000-000000000001');
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
insert into support_fixture(campus)select(internal.campus_support_command('campus.create',null,'{"name":"School Cedar campus","location":null,"reason":"Reviewed campus","confirmConfiguration":true}','campus-create',repeat('a',64),'support')->>'id')::uuid;
select lives_ok($$select internal.campus_support_command('class.campus','30000000-0000-4000-8000-000000000001',jsonb_build_object('campusId',(select campus from support_fixture),'expectedRevision',0,'reason','Reviewed class campus','confirmConfiguration',true),'campus-assign',repeat('b',64),'support')$$,'Class campus assignment explicit and versioned');
select throws_ok($$select internal.campus_support_command('class.campus','30000000-0000-4000-8000-000000000001','{"expectedRevision":1,"reason":"Missing is not unassignment","confirmConfiguration":true}','campus-missing',repeat('b',64),'support')$$,'22023',null,'Missing campusId cannot become an explicit unassignment');
select throws_ok($$select internal.campus_support_command('campus.retire',(select campus from support_fixture),'{"reason":"Current class still uses campus","confirmRetirement":true}','campus-retire-denied',repeat('c',64),'support')$$,'22023',null,'Campus retirement refuses active assigned classes');
update support_fixture set support=(internal.campus_support_command('support.create',null,'{"learnerId":"20000000-0000-4000-8000-000000000012","courseId":"df100000-0000-4000-8000-000000000001","assessmentId":"df110000-0000-4000-8000-000000000001","title":"School checking guide","instructions":"Use the school guide for this task","effectiveFrom":"2026-10-01","effectiveTo":"2026-10-31","studentVisible":true,"parentVisible":true,"reason":"Private approval basis","confirmApproval":true}','support-create',repeat('d',64),'support')->>'id')::uuid;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select is(internal.read_learning_support('{"limit":25,"courseId":"df100000-0000-4000-8000-000000000001","assessmentId":"df110000-0000-4000-8000-000000000001"}')->'items'->0->>'title','School checking guide','Assigned teacher reads instructional support');
select ok(not(internal.read_learning_support('{"limit":25,"courseId":"df100000-0000-4000-8000-000000000001"}')->'items'->0?'approvalReason'),'Teacher receives no private approval basis');
select throws_ok($$select internal.campus_support_command('support.create',null,'{}','support-teacher-denied',repeat('e',64),'support')$$,'42501',null,'Teacher cannot author support approval');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select is(jsonb_array_length(internal.read_learning_support('{"limit":25,"courseId":"df100000-0000-4000-8000-000000000001","assessmentId":"df110000-0000-4000-8000-000000000001"}')->'items'),1,'Own approved task instructions visible');
select throws_ok($$select internal.read_learning_support('{"limit":25}')$$,'42501',null,'Learner cannot enumerate unrestricted support metadata');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
select lives_ok($$select internal.campus_support_command('support.revoke',(select support from support_fixture),'{"expectedRevision":1,"reason":"School revokes support publication","confirmRevocation":true}','support-revoke',repeat('f',64),'support')$$,'Support revocation is explicit and immutable');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select is(jsonb_array_length(internal.read_learning_support('{"limit":25,"courseId":"df100000-0000-4000-8000-000000000001","assessmentId":"df110000-0000-4000-8000-000000000001"}')->'items'),0,'Current parent receives no revoked support');
reset role;
select throws_ok($$update app.learning_support_approvals set reason='Overwrite'where id=(select support from support_fixture)$$,'55000',null,'Approved support history immutable');
select ok(not has_table_privilege('cuevo_api','app.learning_support_approvals','SELECT')and not has_function_privilege('authenticated','internal.read_learning_support(jsonb)','EXECUTE'),'No raw browser or API support grants');
select*from finish();rollback;
